// posts_by_keys returns the rows with the keys `keys`, in their order.
fn (g Graph) posts_by_keys(keys []string) ![]PostNode {
	// as stored: no privacy rule or interceptor hides a row just written
	rows := Graph{
		client: g.client.bypass()
	}.posts().where(load.in_keys('id', keys, .i64)).all()!
	mut by_key := map[string]PostNode{}
	for row in rows {
		by_key[row.post.id.str()] = row
	}
	mut found := []PostNode{cap: keys.len}
	for key in keys {
		found << by_key[key] or {
			return NotFoundError{
				table: 'posts'
			}
		}
	}
	return found
}

// CreatePostInput is what a create of a `posts` row sets, as the GraphQL input
// `CreatePostInput` gives it: `none` and empty lists leave things as
// they are.
pub struct CreatePostInput {
pub mut:
	author_id    ?i64
	title        ?string
	body         ?string
	published_at ?time.Time
}

// set_input sets what `input` gives: clears first, then values, then edges.
pub fn (b PostCreate) set_input(input CreatePostInput) PostCreate {
	mut next := b
	if v := input.author_id {
		next = next.set_author_id(v)
	}
	if v := input.title {
		next = next.set_title(v)
	}
	if v := input.body {
		next = next.set_body(v)
	}
	if v := input.published_at {
		next = next.set_published_at(v)
	}
	return next
}

// UpdatePostInput is what a update of a `posts` row sets, as the GraphQL input
// `UpdatePostInput` gives it: `none` and empty lists leave things as
// they are.
pub struct UpdatePostInput {
pub mut:
	title              ?string
	body               ?string
	published_at       ?time.Time
	clear_published_at bool
}

// set_input sets what `input` gives: clears first, then values, then edges.
pub fn (b PostUpdateOne) set_input(input UpdatePostInput) PostUpdateOne {
	mut next := b
	if input.clear_published_at {
		next = next.clear_published_at()
	}
	if v := input.title {
		next = next.set_title(v)
	}
	if v := input.body {
		next = next.set_body(v)
	}
	if v := input.published_at {
		next = next.set_published_at(v)
	}
	return next
}
